import {test} from 'node:test';import assert from 'node:assert/strict';
import {PAD_DEFAULTS,PAD_ACTIONS,cleanControllerProfile,swapBinding,RepeatInput,curveStick} from '../controller-profile.mjs';
import {InputSampler} from '../input-core.mjs';
const pad=()=>({mapping:'standard',connected:true,axes:[0,0,0,0],buttons:Array.from({length:17},()=>({pressed:false,value:0}))});
test('Remapping swaps two gameplay actions and always preserves every action plus fixed Menu/View',()=>{let p=cleanControllerProfile(null);for(const key of Object.keys(PAD_ACTIONS))for(const button of Object.keys(PAD_ACTIONS).map(k=>PAD_DEFAULTS[k])){p=swapBinding(p,key,button);assert.equal(p.bindings[key],button);assert.equal(new Set(Object.values(p.bindings)).size,16);assert.equal(p.bindings.pause,9);assert.equal(p.bindings.map,8);}});
test('Invalid bindings cannot orphan an action; controller preferences are finite and bounded',()=>{for(const v of [null,[],{bindings:{jump:8}},{bindings:{...PAD_DEFAULTS,fire:0}},{moveDeadzone:Infinity,lookCurve:-50,lookDeadzone:8}]){const p=cleanControllerProfile(v);assert.equal(new Set(Object.values(p.bindings)).size,16);assert.ok(p.lookDeadzone<=.4);assert.ok(p.moveDeadzone>=.08);assert.ok(p.lookCurve>=1);}assert.deepEqual(cleanControllerProfile({bindings:{...PAD_DEFAULTS,fire:0}}).bindings,PAD_DEFAULTS);});
test('Custom triggers route to real actions, held inputs do not leak through a reset, menus can retain their fixed bindings',()=>{const p=pad(),r=new InputSampler(),profile=swapBinding(null,'fire',2);r.read(p,'p',false,profile);p.buttons[2].pressed=true;assert.equal(r.read(p,'p',false,profile).edges.fire,true);r.reset();assert.equal(r.read(p,'p',false,profile).held.fire,false);p.buttons[2].pressed=false;r.read(p,'p',false,profile);p.buttons[2].pressed=true;assert.equal(r.read(p,'p',false,profile).edges.fire,true);const m=new InputSampler();p.buttons[2].pressed=false;m.read(p);p.buttons[2].pressed=true;assert.equal(m.read(p).edges.reload,true);});
test('Navigation has deliberate initial action, bounded auto-repeat and neutral rearming',()=>{const r=new RepeatInput();assert.equal(r.update(1,0),1);assert.equal(r.update(1,.1),0);assert.equal(r.update(1,.35),1);assert.equal(r.update(1,.36),0);assert.equal(r.update(1,100),1);assert.equal(r.update(1,100),0);r.update(0,101);assert.equal(r.update(-1,101),-1);});
test('Fine aiming reduces small deflections without drift or exceeding full diagonal speed',()=>{const p=pad(),r=new InputSampler();p.axes=[.1,.1,.1,.1];assert.deepEqual(r.read(p,'p',false,cleanControllerProfile(null)).look,[0,0]);assert.ok(curveStick([.3,0],1.8)[0]<.3);assert.equal(Math.hypot(...curveStick([1,0],2)),1);});

import {test} from 'node:test';import assert from 'node:assert/strict';
import {LADDERS,ROOFS,ROOF_TASKS,ROOF_THINGS,BEACON_TARGETS,ROOF_ENEMIES} from '../rooftop-world.mjs';
import {createState,step,nearby,interact,jump,toggleGlide,rescue,groundAt,occupied,saveState,fieldScan} from '../model.mjs';
import {cleanExpedition} from '../expedition-core.mjs';
const dt=1/120;const fresh=()=>{const s=createState();for(const b of s.drones)b.hp=0;s.p.invuln=9999;return s;};
const pose=(s,p)=>Object.assign(s.p,{x:p[0],y:p[1],z:p[2],rail:null,ride:null,climb:null,grounded:true,vx:0,vy:0,vz:0});
function at(s,id){const t=ROOF_THINGS.find(t=>t.id===id);pose(s,[t.x,t.y,t.z]);assert.equal(nearby(s)?.id,id);assert.ok(interact(s));}
for(const r of LADDERS)test(r.name+' climbs continuously to its roof and descends to its original street',()=>{const s=fresh();pose(s,r.points[0]);assert.ok(Number.isFinite(groundAt(s.p.x,s.p.z,s.p.y+.1).y));assert.equal(occupied(s.p.x,s.p.y,s.p.z,s),false);assert.equal(nearby(s)?.id,r.id);assert.ok(interact(s));assert.ok(s.p.climb);let last={...s.p};for(let i=0;i<3000&&s.p.climb;i++){step(s,{moveZ:1},dt);assert.ok(Math.hypot(s.p.x-last.x,s.p.y-last.y,s.p.z-last.z)<=.04);last={...s.p};}for(let i=0;i<100;i++)step(s,{},dt);assert.equal(s.p.climb,null);assert.ok(s.p.grounded);assert.equal(s.p.y,ROOFS.find(t=>t.id===r.roof).y);assert.equal(s.stats.rescues,0);assert.ok(interact(s));assert.ok(s.p.climb);for(let i=0;i<3000&&s.p.climb;i++)step(s,{moveZ:-1},dt);for(let i=0;i<80;i++)step(s,{},dt);assert.equal(s.p.y,r.points[0][1]);assert.equal(s.stats.rescues,0);});
test('Ladder holds require input; jump, drop, rescue and save/reload never leave stale climbing',()=>{const s=fresh(),r=LADDERS[0];pose(s,r.points[0]);interact(s);for(let i=0;i<220;i++)step(s,{moveZ:1},dt);const y=s.p.y;for(let i=0;i<120;i++)step(s,{},dt);assert.equal(s.p.y,y);const restored=createState(saveState(s));assert.ok(!restored.p.climb);assert.ok(jump(s));assert.ok(!s.p.climb);assert.ok(s.p.vy>0);pose(s,r.points[0]);interact(s);assert.ok(toggleGlide(s));assert.ok(!s.p.climb);pose(s,r.points[0]);interact(s);rescue(s);assert.ok(!s.p.climb);});
test('Rooftop courier needs all three separately located parcels and pays once',()=>{const s=fresh();at(s,'roof-desk');assert.equal(s.kit.credits,400);for(const id of ['roof-parcel-gannet','roof-parcel-academy','roof-parcel-dawn'])at(s,id);assert.equal(s.kit.credits,400);at(s,'roof-desk');assert.equal(s.kit.credits,580);at(s,'roof-desk');assert.equal(s.kit.credits,580);assert.ok(createState(saveState(s)).expedition.flags.includes('roof-courier-done'));});
test('Three actual rooftop rings must align; repeated energizing cannot duplicate the reward',()=>{const s=fresh();at(s,'roof-desk');for(let i=0;i<3;i++)for(let n=0;n<BEACON_TARGETS[i];n++)at(s,'roof-beacon-'+i);assert.equal(s.kit.credits,400);const restored=createState(saveState(s));assert.deepEqual(restored.expedition.beaconDials,[2,1,3]);at(s,'roof-desk');assert.equal(s.kit.credits,640);at(s,'roof-desk');assert.equal(s.kit.credits,640);});
test('Six surveys are proximity interactions, not remote flyover awards or the old summit task',()=>{const s=fresh();for(const r of ROOFS)at(s,'survey-'+r.id);assert.equal(s.kit.credits,620);assert.ok(s.expedition.flags.includes('roof-surveys-done'));assert.ok(!s.expedition.flags.includes('summits-surveyed'));});
test('New dial storage is sanitized and old campaign flags remain valid',()=>{assert.deepEqual(cleanExpedition({beaconDials:[Infinity,99,-99]}).beaconDials,[0,3,0]);assert.deepEqual(cleanExpedition(null).beaconDials,[0,0,0]);for(const t of ROOF_TASKS)assert.ok(cleanExpedition({flags:[t.flag]}).flags.includes(t.flag));});
test('Longshot and skirmisher are different combat profiles on supported rooftops',()=>{const [a,b]=ROOF_ENEMIES;assert.ok(a.range>b.range&&a.projectileSpeed>b.projectileSpeed&&a.attackDelay>b.attackDelay&&a.hp<b.hp);for(const enemy of ROOF_ENEMIES){assert.equal(groundAt(enemy.x,enemy.z,enemy.y).y,enemy.y-1.05);assert.equal(occupied(enemy.x,enemy.y-1.05,enemy.z),false);}});
